<?php
/**
 * Nahian POS Restaurant Table Delete Handler
 *
 * @package Nahian_POS
 * @since   1.0
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

if ( isset( $_GET['del_table'] ) ) {
	if ( ! current_user_can( 'manage_options' ) ) {
		wp_die( esc_html__( 'You do not have sufficient permissions to perform this action.', 'nahian-restaurant-ordering-system' ) );
	}

	$table_id = absint( $_GET['del_table'] );
	if ( $table_id > 0 ) {
		// Verify CSRF nonce generated by wp_nonce_url() in table-list.php & table-view.php.
		check_admin_referer( 'nrtok_delete_table_' . $table_id );

		global $wpdb;
		$t_tables  = $wpdb->prefix . 'nrtok_tables';
		$svg_check = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';

		if ( $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $t_tables ) ) === $t_tables ) {
			$deleted = $wpdb->delete(
				$t_tables,
				array( 'id' => $table_id ),
				array( '%d' )
			);

			if ( false !== $deleted && $deleted > 0 ) {
				echo '<div class="nrtok-alert" style="display:flex;align-items:center;gap:8px;">' . $svg_check . '<span>' . sprintf( // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
					/* translators: %d: table ID */
					esc_html__( 'Table #%d deleted successfully!', 'nahian-restaurant-ordering-system' ),
					absint( $table_id )
				) . '</span></div>';
			}
		}
	}
}